%[text] # 3 DoF mass-spring oscillator example
%[text] Worked example of the mass-spring system found in [Evaluating applied force reduced-order models: validation](https://doi.org/10.1007/s11071-026-12844-7)
%[text] ![](text:image:31b9)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number, the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\mass_spring_system" %[output:2b6c0310]
set_logging_level(3)
set_visualisation_level(3)

%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\mass\_spring\_roller\\mass\_spring\_roller.m](file:.\\geometry\\mass_spring_roller\\mass_spring_roller.m)), ROM limit and reduction basis needs to be specified.
%[text] Additionally the tangent stiffness at each loadcase is requested for later validation.
%--------- System Settings ---------%
system_name = "mass_spring_roller";
energy_limit = 0.06;
reduction_basis = 1;
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:4f60e9ce] %[output:25d7f990] %[output:36ce65a9]
Static_Data = Static_Dataset(Model); %[output:655c216c] %[output:7e7bc30a] %[output:09b78da7] %[output:7c8afc64]
Static_Data.save_data; %[output:6f6b9e58]
%%
%[text] ### Periodic orbits
%[text] Dynamic solutions are stored as a '`Dynamic_Dataset`' class. Here the instance is initialised, linked to the static dataset and the maximum displacement at the second DoF is requested for each orbit.
rom_name = "mass_spring_roller_1";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:031a30fd]
Dyn_Data = Dyn_Data.remove_solution("all");

Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
Additional_Output.dof = 2;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);
%[text] The `Continuation_Opts` map to the corresponding continuation and collocation settings in COCO.
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 1e-1;
Continuation_Opts.min_inc = 1e-3;

Continuation_Opts.min_discretisation_num = 20;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.frequency_points = [1.86,3]; %adds frequency events to the continutation problem
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:0d2d857e]
compare_solutions("energy","mass_spring_roller_1","all"); %[output:3773495a] %[output:59c28962]
%%
%[text] ### Validation
%[text] The backbone predicted by the {1}-ROM can now be validated against a {1,2} and {1,3} validation basis. 
compare_validation("mass_spring_roller_1","validation error",1,"all"); %[output:106ac9b7] %[output:50a9f04a] %[output:6db93c18] %[output:3c80701a] %[output:5db84d23] %[output:568dedf4] %[output:44cefbc4] %[output:1517876a] %[output:21594298] %[output:8175f6bc] %[output:6d6f1392] %[output:42f0d23a] %[output:9596f454] %[output:0d29264d] %[output:1bef9d54] %[output:9df8a2f7] %[output:7ba79e4b] %[output:28c4feae] %[output:1855c656] %[output:0f1bb4a7] %[output:1138d5c7] %[output:994d6a37] %[output:6d92c968] %[output:7572c43b] %[output:679ad58e] %[output:2bc442f5] %[output:0d8a3930] %[output:1d40837f] %[output:1e465e56] %[output:2d0eab4e] %[output:2a028bbb] %[output:391bf094] %[output:8f8ae508] %[output:9f88827b] %[output:3be6ebf9] %[output:541e8b01] %[output:460a2831] %[output:2ed396b3] %[output:917a1543] %[output:8f48de6c] %[output:1e971157] %[output:19d7e761] %[output:2647a242] %[output:18799bbe] %[output:7b7cd12c] %[output:9d05afd4] %[output:638b70f9] %[output:5c80c5ff] %[output:7dded089] %[output:25644d43] %[output:8e26d527] %[output:0dfe2365] %[output:76e57ea2] %[output:55bf2f2b] %[output:76f1cd82] %[output:133675ca] %[output:1d400041] %[output:80d07da5] %[output:321398de] %[output:5ca3f26b] %[output:09e7f87f] %[output:4a4e9339] %[output:7d585b96] %[output:0f2d0daf] %[output:3520a19c] %[output:528e2ab9] %[output:6362d786] %[output:00545088] %[output:127167bb] %[output:0a949dd2] %[output:70850f2e] %[output:46d21940] %[output:996c7310] %[output:63f1376b]
%%
%[text] ## {1,2}-ROM
%[text] ### Static dataset
%--------- System Settings ---------%
system_name = "mass_spring_roller";
energy_limit = 0.06;
reduction_basis = [1,2];
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:2c1cfb48] %[output:190100f7] %[output:334a2428]
Static_Data = Static_Dataset(Model); %[output:99d22f81] %[output:73a7c3de] %[output:856c148b] %[output:1b94245b]
Static_Data.save_data; %[output:070d4699]
%%
%[text] ### Periodic orbits
rom_name = "mass_spring_roller_12";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:82090245]
Dyn_Data = Dyn_Data.remove_solution("all");

Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
Additional_Output.dof = 2;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);

%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 1e-1;
Continuation_Opts.min_inc = 1e-3;

Continuation_Opts.forward_steps = 200;

Continuation_Opts.min_discretisation_num = 20;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.frequency_points = [1.86,3]; %adds frequency events to the continutation problem
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:4effdc54]
compare_solutions("energy","mass_spring_roller_1","all","mass_spring_roller_12","all") %[output:886bfa94] %[output:0a19a7d1] %[output:409da5d6]
%%
%[text] ### Validation
compare_validation("mass_spring_roller_12","validation error",1,"all"); %[output:3f5a09e7] %[output:9ddabf90] %[output:82acfe25] %[output:9acccf49] %[output:1901f9e5] %[output:934d6afb] %[output:8084df07] %[output:10135ac0] %[output:23655d39] %[output:8f6184ac] %[output:53702829] %[output:5da7dda9] %[output:6c574e46] %[output:0a5a7a02] %[output:11295ceb] %[output:5daaf337] %[output:8a0bd923] %[output:98ae8db1] %[output:15b29796]

